test('REQ-1-3-2: REQ-1-3-2 -the requested workflow,the requested workflow', async ({ page }) => {
  const fileName = `export-escape-${u()}.csv`;
  const csv = 'Name,Note,Qty\n"Smith, John","line1\nline2",\n';

  await importCsv(page, fileName, csv);

